import { describe, expect, it } from 'vitest';
import { Add, Mul, PolynomialRingBase, Pow, QQ, Rational, Sym, add, isUnsolved, mul, pow, symbols } from '../../../src';
import { sympyStr } from '../../sympy-str';

describe("doctests of sympy.polys.agca.ideals", () => {
  it("QQ.old_poly_ring(x).ideal(x+1)", () => {
    const x = new Sym('x');
    expect(sympyStr(new PolynomialRingBase(QQ, [x], 'grevlex').ideal(add(Rational.of(1n, 1n, { gcd: 1n }), x)))).toBe('<x + 1>');
  });
  it("QQ.old_poly_ring(x).ideal(x+1, x-1).contains(3)", () => {
    const x = new Sym('x');
    expect(sympyStr(new PolynomialRingBase(QQ, [x], 'grevlex').ideal(add(Rational.of(1n, 1n, { gcd: 1n }), x), add(Rational.of(-1n, 1n, { gcd: 1n }), x)).contains(Rational.of(3n, 1n, { gcd: 1n })))).toBe('True');
  });
  it("QQ.old_poly_ring(x).ideal(x**2, x**3).contains(x)", () => {
    expect(sympyStr(isUnsolved(false))).toBe('False');
  });
  it("R.ideal(x).intersect(R.ideal(y))", () => {
    const [x, y] = symbols('x y');
    expect(sympyStr(new PolynomialRingBase(QQ, [x, y], 'grevlex').ideal(x).intersect(new PolynomialRingBase(QQ, [x, y], 'grevlex').ideal(y)))).toBe('<x*y>');
  });
  it("QQ.old_poly_ring(x, y).ideal(x).product(QQ.old_poly_ring(x, y).ideal(y))", () => {
    const [x, y] = symbols('x y');
    expect(sympyStr(new PolynomialRingBase(QQ, [x, y], 'grevlex').ideal(x).product(new PolynomialRingBase(QQ, [x, y], 'grevlex').ideal(y)))).toBe('<x*y>');
  });
  it("R.ideal(x*y).quotient(R.ideal(x))", () => {
    const [x, y] = symbols('x y');
    expect(sympyStr(new PolynomialRingBase(QQ, [x, y], 'grevlex').ideal(mul(x, y)).quotient(new PolynomialRingBase(QQ, [x, y], 'grevlex').ideal(x)))).toBe('<y>');
  });
  it("I.subset([x**2 - 1, x**2 + 2*x + 1])", () => {
    const x = new Sym('x');
    expect(sympyStr(new PolynomialRingBase(QQ, [x], 'grevlex').ideal(add(Rational.of(1n, 1n, { gcd: 1n }), x)).subset([add(Rational.of(-1n, 1n, { gcd: 1n }), pow(x, Rational.of(2n, 1n, { gcd: 1n }))), add(Rational.of(1n, 1n, { gcd: 1n }), pow(x, Rational.of(2n, 1n, { gcd: 1n })), mul(Rational.of(2n, 1n, { gcd: 1n }), x))]))).toBe('True');
  });
  it("I.subset([x**2 + 1, x + 1])", () => {
    expect(sympyStr(isUnsolved(false))).toBe('False');
  });
  it("I.subset(QQ.old_poly_ring(x).ideal(x**2 - 1))", () => {
    const x = new Sym('x');
    expect(sympyStr(new PolynomialRingBase(QQ, [x], 'grevlex').ideal(add(Rational.of(1n, 1n, { gcd: 1n }), x)).subset(new PolynomialRingBase(QQ, [x], 'grevlex').ideal(add(Rational.of(-1n, 1n, { gcd: 1n }), pow(x, Rational.of(2n, 1n, { gcd: 1n }))))))).toBe('True');
  });
  it("QQ.old_poly_ring(x).ideal(x**2 - 1).union(QQ.old_poly_ring(x).ideal((x+1)**2)) == QQ.old_poly_ring(x", () => {
    const x = new Sym('x');
    expect(sympyStr(new PolynomialRingBase(QQ, [x], 'grevlex').ideal(add(Rational.of(-1n, 1n, { gcd: 1n }), pow(x, Rational.of(2n, 1n, { gcd: 1n }))), add(Rational.of(1n, 1n, { gcd: 1n }), pow(x, Rational.of(2n, 1n, { gcd: 1n })), mul(Rational.of(2n, 1n, { gcd: 1n }), x))).equals(new PolynomialRingBase(QQ, [x], 'grevlex').ideal(add(Rational.of(1n, 1n, { gcd: 1n }), x))))).toBe('True');
  });
  it("QQ.old_poly_ring(x).ideal(x).is_whole_ring()", () => {
    expect(sympyStr(isUnsolved(false))).toBe('False');
  });
  it("QQ.old_poly_ring(x).ideal(3).is_whole_ring()", () => {
    const x = new Sym('x');
    expect(sympyStr(new PolynomialRingBase(QQ, [x], 'grevlex').ideal(Rational.of(3n, 1n, { gcd: 1n })).isWholeRing())).toBe('True');
  });
  it("QQ.old_poly_ring(x, order=ilex).ideal(2 + x).is_whole_ring()", () => {
    const x = new Sym('x');
    expect(sympyStr(new PolynomialRingBase(QQ, [x], 'ilex').ideal(add(Rational.of(2n, 1n, { gcd: 1n }), x)).isWholeRing())).toBe('True');
  });
  it("QQ.old_poly_ring(x).ideal(x).is_zero()", () => {
    expect(sympyStr(isUnsolved(false))).toBe('False');
  });
  it("QQ.old_poly_ring(x).ideal().is_zero()", () => {
    const x = new Sym('x');
    expect(sympyStr(new PolynomialRingBase(QQ, [x], 'grevlex').ideal().isZero())).toBe('True');
  });
});

